INSERT INTO coffee_products (id, name, slug, description, tasting_notes, origin_type, shop_category_slug, subtitle, roast_level, hero_image_path, active) VALUES ('coffee-decaf-swiss-water', 'Swiss Water Decaf', 'swiss-water-decaf', 'Swiss Water process decaf with clean sweetness and enough body for espresso and filter. A strong decaf menu option under your brand.', ARRAY['Toffee','Red apple','Milk chocolate']::text[], 'Decaf', 'decaf', 'Chemical-free decaffeination, full flavour.', 'Medium', '/mockups/bag-black.svg', true);
INSERT INTO coffee_products (id, name, slug, description, tasting_notes, origin_type, shop_category_slug, subtitle, roast_level, hero_image_path, active) VALUES ('coffee-decaf-sugar-cane', 'Sugar Cane Decaf', 'sugar-cane-decaf', 'Sugar cane (EA) process decaf with rounded sweetness and biscuit notes. Works well for batch brew and cafetiere service.', ARRAY['Biscuit','Panela','Baked apple']::text[], 'Decaf', 'decaf', 'EA process with rounded sweetness.', 'Medium', '/mockups/bag-kraft.svg', true);
INSERT INTO coffee_products (id, name, slug, description, tasting_notes, origin_type, shop_category_slug, subtitle, roast_level, hero_image_path, active) VALUES ('coffee-french-roast', 'French Roast', 'french-roast', 'Slow-developed dark roast with smoky sweetness and low acidity. For menus that still lean into bold, traditional profiles.', ARRAY['Smoked caramel','Bittersweet cocoa','Walnut']::text[], 'Dark roast', 'dark-roast', 'Very dark for classic dark-roast drinkers.', 'Dark', '/mockups/bag-black.svg', true);
INSERT INTO coffee_products (id, name, slug, description, tasting_notes, origin_type, shop_category_slug, subtitle, roast_level, hero_image_path, active) VALUES ('coffee-taster-trio', 'Taster Trio (3 × 200g)', 'taster-trio', 'Three 200g bags: House Blend, a single origin, and your choice of decaf (we rotate seasonally). Perfect for cupping with your team or sampling at the pass.', ARRAY['Sample pack','Mixed roast levels','Cupping notes included']::text[], 'Sample', 'samples', 'Trial three profiles before you scale.', 'Mixed', '/mockups/bag-kraft.svg', true);
